INSERT INTO juegos (id, nombre, categoria, imagen, resumen, descripcion, anio, plataforma, ambientacion, orden) VALUES
  ('re1', 'Resident Evil (1996)', 'Principal', 'img/ilustraciones/ubicaciones/mansion-spencer.svg', 'El origen de la saga: el equipo Alpha de S.T.A.R.S. queda atrapado en la Mansión Spencer.', 'Julio de 1998. Tras la desaparición del equipo Bravo en las montañas Arklay, el equipo Alpha de S.T.A.R.S. se refugia en una mansión aislada. Chris Redfield y Jill Valentine descubren que es la fachada de un laboratorio de Umbrella donde se experimenta con el Virus-T.', 1996, 'PlayStation', 'Mansión Spencer, montañas Arklay (1998)', 1),
  ('re2-1998', 'Resident Evil 2 (1998)', 'Principal', 'img/escenarios/re2_calle.webp', 'Leon y Claire llegan a una Raccoon City devorada por el brote del Virus-T.', 'Septiembre de 1998. En su primer día como policía, Leon S. Kennedy coincide con Claire Redfield, que busca a su hermano Chris. La comisaría R.P.D. y los laboratorios subterráneos de Umbrella esconden el Virus-G de William Birkin.', 1998, 'PlayStation', 'Raccoon City (1998)', 2),
  ('re3-1999', 'Resident Evil 3: Nemesis', 'Principal', 'img/escenarios/re3_torre.webp', 'Jill Valentine intenta escapar de Raccoon City mientras Nemesis la persigue.', 'Jill Valentine, superviviente de la mansión, trata de huir de la ciudad con la ayuda del mercenario Carlos Oliveira. Umbrella envía a Nemesis para eliminar a los miembros de S.T.A.R.S. antes de que el gobierno destruya Raccoon City.', 1999, 'PlayStation', 'Raccoon City (1998)', 3),
  ('survivor', 'Resident Evil Survivor', 'Spin-off', 'img/ilustraciones/juegos/spinoffs-no-canon.svg', 'Primer juego en primera persona de la saga, ambientado en la isla Sheena.', 'Ark Thompson despierta sin memoria en la isla Sheena, una ciudad controlada por Umbrella y dirigida por Vincent Goldman. Es un juego de disparos con pistola de luz que se considera fuera de la historia principal.', 2000, 'PlayStation', 'Isla Sheena (1998)', 4),
  ('code-veronica', 'Resident Evil Code: Veronica', 'Principal', 'img/ilustraciones/ubicaciones/isla-rockfort.svg', 'Claire busca a Chris y acaba prisionera en la isla Rockfort de los Ashford.', 'Diciembre de 1998. Claire es capturada en el laboratorio de Umbrella en París y enviada a la isla Rockfort. Junto a Steve Burnside descubre el virus T-Veronica de Alexia Ashford. Chris toma el relevo en la base de la Antártida.', 2000, 'Dreamcast', 'Isla Rockfort y la Antártida (1998)', 5),
  ('gaiden', 'Resident Evil Gaiden', 'Spin-off', 'img/ilustraciones/ubicaciones/queen-zenobia.svg', 'Leon y Barry investigan un brote en el crucero Starlight.', 'Aventura para Game Boy Color en la que Barry Burton busca a Leon, desaparecido a bordo de un barco infestado. No forma parte del canon oficial.', 2001, 'Game Boy Color', 'Crucero Starlight', 6),
  ('re-remake', 'Resident Evil (remake)', 'Remake', 'img/ilustraciones/ubicaciones/mansion-spencer.svg', 'Reconstrucción completa del primer juego con nuevas zonas y la historia de Lisa Trevor.', 'Capcom rehízo desde cero el juego de 1996 con escenarios prerenderizados, nuevos acertijos, los Crimson Head y la trágica historia de Lisa Trevor, la hija de George Trevor, el arquitecto de la mansión.', 2002, 'Nintendo GameCube', 'Mansión Spencer (1998)', 7),
  ('re0', 'Resident Evil 0', 'Principal', 'img/ilustraciones/ubicaciones/ecliptic-express.svg', 'Precuela directa: Rebecca Chambers y Billy Coen sobreviven al tren Ecliptic Express.', 'Horas antes de los hechos de la mansión, la novata del equipo Bravo, Rebecca Chambers, se une al exmarine Billy Coen. Juntos recorren el Ecliptic Express y el centro de formación de Umbrella, donde descubren a James Marcus, uno de los fundadores de la compañía.', 2002, 'Nintendo GameCube', 'Ecliptic Express y centro de formación de Umbrella (1998)', 8),
  ('outbreak', 'Resident Evil Outbreak', 'Multijugador', 'img/escenarios/re3_calles.webp', 'Ocho ciudadanos corrientes intentan sobrevivir al brote de Raccoon City.', 'Primer juego cooperativo en línea de la saga. Sus protagonistas no son agentes, sino vecinos de Raccoon City como la periodista Alyssa Ashcroft. Tuvo una segunda parte, Outbreak File #2 (2004).', 2003, 'PlayStation 2', 'Raccoon City (1998)', 9),
  ('dead-aim', 'Resident Evil: Dead Aim', 'Spin-off', 'img/ilustraciones/juegos/spinoffs-no-canon.svg', 'Bruce McGivern y Fong Ling persiguen un barco de Umbrella secuestrado.', 'Juego de disparos compatible con pistola de luz. Un exempleado de Umbrella roba el Virus-T y amenaza con liberarlo en Estados Unidos.', 2003, 'PlayStation 2', 'Crucero Spencer Rain e isla (2002)', 10),
  ('re4-2005', 'Resident Evil 4 (2005)', 'Principal', 'img/escenarios/re4_granja.webp', 'Leon viaja a un pueblo de España para rescatar a la hija del presidente.', '2004. Leon, ya agente del gobierno, busca a Ashley Graham en una región rural de España. Los aldeanos están controlados por Las Plagas, el parásito de la secta Los Iluminados liderada por Osmund Saddler. Cambió para siempre los juegos de acción en tercera persona.', 2005, 'Nintendo GameCube', 'Pueblo de España, castillo e isla (2004)', 11),
  ('umbrella-chronicles', 'Resident Evil: The Umbrella Chronicles', 'Spin-off', 'img/ilustraciones/organizaciones/umbrella.svg', 'Repaso sobre raíles de la caída de Umbrella, con capítulos inéditos.', 'Recorre los sucesos de 1998 y añade la misión de Chris y Jill en las instalaciones de Umbrella en el Cáucaso (2003), donde cae definitivamente la compañía y aparece la inteligencia artificial Reina Roja.', 2007, 'Wii', '1998-2003', 12),
  ('re5', 'Resident Evil 5', 'Principal', 'img/escenarios/re5_kijuju.webp', 'Chris y Sheva se enfrentan a Wesker y al Uroboros en África.', '2009. La BSAA envía a Chris Redfield y Sheva Alomar a Kijuju, donde los Majini atacan a los soldados. Detrás están Tricell, Excella Gionne y Albert Wesker, que quiere liberar el Uroboros sobre el mundo. Chris descubre que Jill sigue viva.', 2009, 'PlayStation 3, Xbox 360', 'Kijuju, África (2009)', 13),
  ('darkside-chronicles', 'Resident Evil: The Darkside Chronicles', 'Spin-off', 'img/escenarios/re2_cloacas.webp', 'Versión sobre raíles de Raccoon City, Code: Veronica y una misión en Sudamérica.', 'Incluye la Operación Javier (2002), en la que Leon y Jack Krauser investigan a un narcotraficante que esconde un virus en Amparo.', 2009, 'Wii', '1998-2002', 14),
  ('mercenaries-3d', 'Resident Evil: The Mercenaries 3D', 'Spin-off', 'img/ilustraciones/juegos/spinoffs-no-canon.svg', 'El modo Mercenarios convertido en un juego completo para Nintendo 3DS.', 'Contrarreloj de acción con personajes como Chris, Jill, Wesker, HUNK, Krauser o Rebecca. No tiene historia canónica.', 2011, 'Nintendo 3DS', 'Escenarios de RE4 y RE5', 15),
  ('revelations', 'Resident Evil: Revelations', 'Principal', 'img/ilustraciones/ubicaciones/queen-zenobia.svg', 'Jill y Parker exploran el crucero Queen Zenobia en pleno Mediterráneo.', 'Entre RE4 y RE5, la BSAA investiga a Veltro, el grupo terrorista que destruyó Terragrigia con el virus T-Abyss. Recupera el terror de los primeros juegos a bordo de un barco abandonado.', 2012, 'Nintendo 3DS', 'Queen Zenobia, Mediterráneo (2005)', 16),
  ('operation-raccoon-city', 'Resident Evil: Operation Raccoon City', 'Spin-off', 'img/ilustraciones/organizaciones/ubcs.svg', 'Un equipo de Umbrella limpia pruebas durante la destrucción de Raccoon City.', 'Shooter por equipos en el que el escuadrón Wolfpack de Umbrella debe eliminar testigos del brote. Ofrece una historia alternativa no canónica.', 2012, 'PlayStation 3, Xbox 360, PC', 'Raccoon City (1998)', 17),
  ('re6', 'Resident Evil 6', 'Principal', 'img/escenarios/re6_lanshiang.webp', 'Leon, Chris, Jake y Ada viven el mayor ataque bioterrorista de la historia.', '2012-2013. Neo-Umbrella libera el Virus-C en Tall Oaks y Lanshiang. Cuatro campañas cruzadas cuentan la caída del presidente Benford, la traición de Derek Simmons y la aparición de Jake Muller, hijo de Wesker.', 2012, 'PlayStation 3, Xbox 360', 'Tall Oaks, Edonia y Lanshiang (2012-2013)', 18),
  ('revelations-2', 'Resident Evil: Revelations 2', 'Principal', 'img/ilustraciones/ubicaciones/sushestvovanie.svg', 'Claire y Moira Burton despiertan en una isla prisión dirigida por Alex Wesker.', 'Un ataque a una fiesta de TerraSave lleva a Claire y Moira a la isla Sushestvovanie. Seis meses después, Barry Burton llega buscando a su hija y encuentra a la niña Natalia Korda.', 2015, 'PlayStation 4, Xbox One, PC', 'Isla Sushestvovanie (2011)', 19),
  ('umbrella-corps', 'Umbrella Corps', 'Multijugador', 'img/ilustraciones/organizaciones/umbrella.svg', 'Shooter competitivo de mercenarios en escenarios clásicos de la saga.', 'Juego multijugador en línea ambientado tras la caída de Umbrella, con corporaciones que contratan mercenarios para conseguir datos de bioarmas. No tuvo continuidad.', 2016, 'PlayStation 4, PC', 'Varios', 20),
  ('re7', 'Resident Evil 7: Biohazard', 'Principal', 'img/escenarios/re7_casa_vieja.webp', 'Ethan Winters entra en la casa de los Baker buscando a su mujer.', '2017. Primera entrega principal en primera persona. Ethan llega a una granja de Luisiana donde Jack, Marguerite y Lucas Baker están controlados por Eveline, un arma biológica creada con el Moho.', 2017, 'PlayStation 4, Xbox One, PC', 'Dulvey, Luisiana (2017)', 21),
  ('re2-remake', 'Resident Evil 2 (remake)', 'Remake', 'img/escenarios/re2_vestibulo.webp', 'Nueva versión de RE2 con cámara al hombro y un Mr. X implacable.', 'Reimaginación completa del clásico de 1998 con el motor RE Engine. Amplía la comisaría, el orfanato y el laboratorio NEST, y convierte a Mr. X en un perseguidor constante.', 2019, 'PlayStation 4, Xbox One, PC', 'Raccoon City (1998)', 22),
  ('re3-remake', 'Resident Evil 3 (remake)', 'Remake', 'img/escenarios/re3_calles.webp', 'Jill y Carlos vuelven a escapar de Nemesis en una Raccoon City renovada.', 'Nueva versión de RE3 que da más peso a Carlos y al U.B.C.S., añade el hospital y el laboratorio NEST 2, y cambia varias formas de Nemesis.', 2020, 'PlayStation 4, Xbox One, PC', 'Raccoon City (1998)', 23),
  ('resistance', 'Resident Evil Resistance', 'Multijugador', 'img/escenarios/re3_metro.webp', 'Cuatro supervivientes contra un mente maestra que controla las trampas.', 'Modo asimétrico incluido con RE3 (remake): un jugador hace de mente maestra, como Annette Birkin, y coloca criaturas y cámaras mientras cuatro supervivientes intentan escapar.', 2020, 'PlayStation 4, Xbox One, PC', 'Raccoon City', 24),
  ('re8', 'Resident Evil Village', 'Principal', 'img/escenarios/re8_aldea.webp', 'Ethan Winters busca a su hija Rose en una aldea de Europa del Este.', '2021. Tras el secuestro de Rose, Ethan Winters llega a una aldea dominada por Madre Miranda y sus cuatro señores: Lady Dimitrescu, Donna Beneviento, Salvatore Moreau y Karl Heisenberg. Su poder procede del Megamiceto. Incluye el epílogo Shadows of Rose.', 2021, 'PlayStation 5, Xbox Series X|S, PC', 'Aldea de Europa del Este (2021)', 25),
  ('reverse', 'Resident Evil Re:Verse', 'Multijugador', 'img/ilustraciones/juegos/spinoffs-no-canon.svg', 'Duelos en línea entre personajes clásicos que mutan en bioarmas al morir.', 'Juego competitivo en el que, al caer, el jugador vuelve como criatura.', 2022, 'PlayStation 4, Xbox One, PC', 'Raccoon City', 26),
  ('re4-remake', 'Resident Evil 4 (remake)', 'Remake', 'img/escenarios/re4_plaza.webp', 'Nueva versión del viaje de Leon a España, más oscura y con Luis y Ashley ampliados.', 'Reimaginación del juego de 2005 con el RE Engine. Añade el combate con cuchillo y las paradas, amplía a Luis Serra y Ashley, y suma el capítulo Separate Ways de Ada Wong.', 2023, 'PlayStation 5, Xbox Series X|S, PC', 'España rural (2004)', 27),
  ('requiem', 'Resident Evil Requiem', 'Principal', 'img/escenarios/re9_hotel.webp', 'Grace Ashcroft investiga muertes misteriosas que la llevan de vuelta a Raccoon City.', 'Novena entrega principal. La analista del FBI Grace Ashcroft, hija de la periodista Alyssa Ashcroft, investiga una serie de muertes vinculadas al hotel Wrenwood, donde murió su madre. Leon S. Kennedy vuelve como segundo protagonista y la historia regresa a las ruinas de Raccoon City.', 2026, 'PlayStation 5, Xbox Series X|S, PC, Nintendo Switch 2', 'Hotel Wrenwood y ruinas de Raccoon City', 28);
