INSERT INTO personajes (id, nombre, imagen, resumen, descripcion, primera_aparicion, afiliacion, estado, nacimiento, orden) VALUES
  ('leon', 'Leon S. Kennedy', 'img/retratos/leon.webp', 'Policía novato en Raccoon City y después agente especial del gobierno de EE. UU.', 'Leon sobrevivió a su primer día como agente de la R.P.D. durante el brote de Raccoon City. El gobierno lo reclutó y lo entrenó como agente especial: rescató a Ashley Graham en España, perdió al presidente Benford en Tall Oaks y ha combatido el bioterrorismo por todo el mundo.', 'Resident Evil 2', 'R.P.D., DSO (gobierno de EE. UU.)', 'Vivo', '1977', 1),
  ('jill', 'Jill Valentine', 'img/retratos/jill.webp', 'Miembro de S.T.A.R.S., superviviente de la mansión y de Raccoon City.', 'Experta en explosivos y cerraduras, Jill sobrevivió a la Mansión Spencer y escapó de Raccoon City perseguida por Nemesis. Cofundó la BSAA y estuvo años desaparecida, controlada por Wesker, hasta que Chris la liberó en África.', 'Resident Evil (1996)', 'S.T.A.R.S., BSAA', 'Viva', '1974', 2),
  ('chris', 'Chris Redfield', 'img/retratos/chris.webp', 'Miembro de S.T.A.R.S. que dedicó su vida a acabar con Umbrella y el bioterrorismo.', 'Expiloto de las fuerzas aéreas, Chris formaba parte del equipo Alpha. Persiguió a Umbrella por todo el mundo, cofundó la BSAA, acabó con Wesker en África y, ya al frente de la unidad Hound Wolf, ayudó a Ethan Winters en Luisiana y en la aldea.', 'Resident Evil (1996)', 'S.T.A.R.S., BSAA, Hound Wolf', 'Vivo', '1973', 3),
  ('claire', 'Claire Redfield', 'img/retratos/claire.webp', 'Hermana de Chris; llegó a Raccoon City buscándolo y acabó luchando contra el bioterrorismo.', 'Universitaria y motorista, Claire sobrevivió a Raccoon City junto a Leon y protegió a Sherry Birkin. Después fue prisionera en la isla Rockfort y trabajó en TerraSave ayudando a víctimas de ataques biológicos.', 'Resident Evil 2', 'TerraSave', 'Viva', '1979', 4),
  ('ada', 'Ada Wong', 'img/retratos/ada.webp', 'Espía misteriosa que aparece siempre donde hay una muestra valiosa.', 'Ada se infiltró en Raccoon City para robar una muestra del Virus-G y desde entonces trabaja para clientes que nunca revela. Sus caminos se cruzan una y otra vez con los de Leon.', 'Resident Evil 2', 'Independiente', 'Viva', 'Desconocido', 5),
  ('wesker', 'Albert Wesker', 'img/retratos/wesker.webp', 'Capitán de S.T.A.R.S. e investigador de Umbrella que traicionó a su equipo.', 'Wesker llevó a su propio equipo a la mansión para recoger datos de combate de las bioarmas. Sobrevivió gracias a un virus experimental y años después, con Tricell, intentó liberar el Uroboros en todo el planeta. Murió en un volcán de África en 2009.', 'Resident Evil (1996)', 'Umbrella, S.T.A.R.S., Tricell', 'Fallecido (2009)', '1960', 6),
  ('rebecca', 'Rebecca Chambers', 'img/ilustraciones/personajes/rebecca.svg', 'Médica del equipo Bravo de S.T.A.R.S. con solo 18 años.', 'La más joven de S.T.A.R.S. sobrevivió al Ecliptic Express junto a Billy Coen y se reunió después con Chris en la mansión. Hoy es investigadora y ha colaborado con Leon y Chris contra nuevas amenazas virales.', 'Resident Evil (1996)', 'S.T.A.R.S.', 'Viva', '1980', 7),
  ('barry', 'Barry Burton', 'img/ilustraciones/personajes/barry.svg', 'Experto en armas del equipo Alpha, chantajeado por Wesker en la mansión.', 'Veterano de S.T.A.R.S. y amigo de Chris. Wesker amenazó a su familia para que lo ayudara, pero acabó ayudando a Jill. En Revelations 2 viaja a Sushestvovanie para rescatar a su hija Moira.', 'Resident Evil (1996)', 'S.T.A.R.S.', 'Vivo', 'Desconocido', 8),
  ('billy', 'Billy Coen', 'img/ilustraciones/personajes/billy.svg', 'Exmarine condenado a muerte que se alía con Rebecca.', 'Billy escapaba de un traslado de prisioneros cuando se encontró con Rebecca en el Ecliptic Express. Ella lo dio por muerto para que pudiera empezar de cero.', 'Resident Evil 0', 'Ninguna', 'Desconocido', '1972', 9),
  ('brad', 'Brad Vickers', 'img/retratos/brad.webp', 'Piloto del helicóptero de S.T.A.R.S., apodado «Chickenheart».', 'Abandonó a sus compañeros en las montañas Arklay por miedo, aunque volvió a rescatarlos. En Raccoon City fue infectado y Nemesis lo mató frente a la comisaría.', 'Resident Evil (1996)', 'S.T.A.R.S.', 'Fallecido (1998)', 'Desconocido', 10),
  ('sherry', 'Sherry Birkin', 'img/retratos/sherry.webp', 'Hija de William y Annette Birkin, superviviente de Raccoon City.', 'De niña fue infectada con el Virus-G, que acabó dándole capacidad de regeneración. El gobierno la convirtió en agente y en RE6 protege a Jake Muller.', 'Resident Evil 2', 'Gobierno de EE. UU.', 'Viva', '1986', 11),
  ('carlos', 'Carlos Oliveira', 'img/retratos/carlos.webp', 'Mercenario del U.B.C.S. que ayuda a Jill a escapar de Raccoon City.', 'Carlos llegó a la ciudad creyendo que iba a rescatar civiles. Al descubrir que Umbrella usaba a su unidad como cebo, se volvió contra la compañía.', 'Resident Evil 3: Nemesis', 'U.B.C.S.', 'Vivo', 'Desconocido', 12),
  ('tyrell', 'Tyrell Patrick', 'img/retratos/tyrell.webp', 'Compañero de Carlos en el U.B.C.S. en el remake de RE3.', 'Mercenario veterano y experto en comunicaciones. Ayuda a Jill y Carlos a llegar al hospital y se sacrifica para frenar a Nemesis.', 'Resident Evil 3 (remake)', 'U.B.C.S.', 'Fallecido (1998)', 'Desconocido', 13),
  ('nikolai', 'Nikolai Zinoviev', 'img/retratos/nikolai.webp', 'Mercenario del U.B.C.S. que trabaja en secreto para Umbrella.', 'Nikolai era un «perro guardián»: su misión real era recoger datos de combate de las bioarmas y eliminar a quien se interpusiera.', 'Resident Evil 3: Nemesis', 'U.B.C.S., Umbrella', 'Desconocido', 'Desconocido', 14),
  ('mikhail', 'Mikhail Victor', 'img/retratos/mikhail.webp', 'Jefe de pelotón del U.B.C.S. herido durante el brote.', 'Mikhail protegió a los civiles del vagón de metro y se inmoló con una granada para intentar detener a Nemesis.', 'Resident Evil 3: Nemesis', 'U.B.C.S.', 'Fallecido (1998)', 'Desconocido', 15),
  ('marvin', 'Marvin Branagh', 'img/retratos/marvin.webp', 'Teniente de la R.P.D. que recibe a Leon y Claire en la comisaría.', 'Herido por un zombi, Marvin ayudó a los recién llegados con información y llaves hasta que el virus lo transformó.', 'Resident Evil 2', 'R.P.D.', 'Fallecido (1998)', 'Desconocido', 16),
  ('irons', 'Brian Irons', 'img/ilustraciones/personajes/irons.svg', 'Corrupto jefe de policía de Raccoon City a sueldo de Umbrella.', 'Irons ocultó pruebas del laboratorio a cambio de sobornos y saboteó la defensa de la comisaría. Murió a manos del G-adulto.', 'Resident Evil 2', 'R.P.D., Umbrella', 'Fallecido (1998)', 'Desconocido', 17),
  ('birkin', 'William Birkin', 'img/retratos/birkin.webp', 'Científico de Umbrella, creador del Virus-G.', 'Genio precoz, Birkin trabajó con Wesker en el laboratorio de Arklay. Cuando Umbrella le arrebató el Virus-G, se lo inyectó y se convirtió en el monstruo G.', 'Resident Evil 2', 'Umbrella', 'Fallecido (1998)', '1962', 18),
  ('annette', 'Annette Birkin', 'img/ilustraciones/personajes/annette.svg', 'Científica de Umbrella, esposa de William y madre de Sherry.', 'Annette protegió el trabajo de su marido hasta el final y murió ayudando a destruir el laboratorio NEST.', 'Resident Evil 2', 'Umbrella', 'Fallecida (1998)', 'Desconocido', 19),
  ('hunk', 'HUNK', 'img/ilustraciones/personajes/hunk.svg', 'Agente de élite de Umbrella apodado «La Muerte».', 'Siempre sale con vida de las misiones en las que muere el resto de su equipo. Fue quien robó el Virus-G de Birkin en Raccoon City.', 'Resident Evil 2', 'Umbrella (U.S.S.)', 'Vivo', 'Desconocido', 20),
  ('spencer', 'Oswell E. Spencer', 'img/ilustraciones/personajes/spencer.svg', 'Fundador de Umbrella obsesionado con convertirse en un dios.', 'Aristócrata europeo que financió la investigación del Progenitor. Su proyecto Wesker creó a niños superdotados para una nueva humanidad. Albert Wesker lo mató en 2006.', 'Resident Evil (1996)', 'Umbrella', 'Fallecido (2006)', 'Desconocido', 21),
  ('marcus', 'James Marcus', 'img/ilustraciones/personajes/james-marcus.svg', 'Cofundador de Umbrella y creador del Virus-T.', 'Investigador brillante que dirigió el centro de formación de Umbrella. Spencer ordenó asesinarlo en 1988, pero sus sanguijuelas lo trajeron de vuelta.', 'Resident Evil 0', 'Umbrella', 'Fallecido (1998)', '1939', 22),
  ('alexia', 'Alexia Ashford', 'img/ilustraciones/personajes/alexia.svg', 'Niña prodigio de la familia Ashford y creadora del T-Veronica.', 'Con solo diez años desarrolló el virus T-Veronica. Se congeló durante quince años para adaptarse a él y despertó en la base de la Antártida.', 'Resident Evil Code: Veronica', 'Umbrella (familia Ashford)', 'Fallecida (1998)', '1971', 23),
  ('alfred', 'Alfred Ashford', 'img/ilustraciones/personajes/alfred.svg', 'Hermano gemelo de Alexia y comandante de la isla Rockfort.', 'Alfred, inestable y obsesionado con su hermana, se hacía pasar por ella vistiéndose como Alexia.', 'Resident Evil Code: Veronica', 'Umbrella (familia Ashford)', 'Fallecido (1998)', '1971', 24),
  ('steve', 'Steve Burnside', 'img/ilustraciones/personajes/steve.svg', 'Joven prisionero de Rockfort que acompaña a Claire.', 'Hijo de un empleado de Umbrella, Steve escapó con Claire hasta que Alexia lo infectó con el T-Veronica.', 'Resident Evil Code: Veronica', 'Ninguna', 'Fallecido (1998)', '1981', 25),
  ('sergei', 'Sergei Vladimir', 'img/ilustraciones/personajes/sergei.svg', 'Coronel de Umbrella y guardián de la Reina Roja.', 'Leal a Spencer, dirigía las instalaciones de Umbrella en el Cáucaso. Murió al enfrentarse a Wesker en 2003.', 'Resident Evil: Survivor 2 / Umbrella Chronicles', 'Umbrella', 'Fallecido (2003)', 'Desconocido', 26),
  ('ashley', 'Ashley Graham', 'img/retratos/ashley.webp', 'Hija del presidente de EE. UU., secuestrada por Los Iluminados.', 'Los Iluminados la infectaron con una Plaga para controlar al gobierno a través de ella. Leon la rescató y le extirpó el parásito.', 'Resident Evil 4', 'Familia presidencial', 'Viva', '1984', 27),
  ('luis', 'Luis Serra', 'img/retratos/luis.webp', 'Investigador español que trabajó para Saddler y se arrepintió.', 'Luis ayudó a crear las Plagas dominantes y después intentó destruirlas. Murió a manos de Saddler tras entregar a Leon el fármaco que retrasa la infección.', 'Resident Evil 4', 'Los Iluminados (antiguo)', 'Fallecido (2004)', 'Desconocido', 28),
  ('krauser', 'Jack Krauser', 'img/retratos/krauser.webp', 'Excompañero de Leon que se alió con Wesker.', 'Soldado de élite herido en la Operación Javier. Se unió a Wesker e infiltró en Los Iluminados, donde se enfrentó a Leon con un brazo mutado.', 'Resident Evil 4', 'Ejército de EE. UU., Wesker', 'Fallecido (2004)', 'Desconocido', 29),
  ('saddler', 'Osmund Saddler', 'img/retratos/saddler.webp', 'Líder de Los Iluminados y amo de Las Plagas.', 'Gracias a la Plaga dominante controla a todos los infectados. Planeaba dominar el mundo infectando a Ashley Graham.', 'Resident Evil 4', 'Los Iluminados', 'Fallecido (2004)', 'Desconocido', 30),
  ('salazar', 'Ramón Salazar', 'img/retratos/salazar.webp', 'Octavo castellano del castillo, cuya familia encerró a Las Plagas.', 'Joven y caprichoso, liberó a Las Plagas que sus antepasados habían sellado y puso su castillo al servicio de Saddler.', 'Resident Evil 4', 'Los Iluminados', 'Fallecido (2004)', '1984', 31),
  ('mendez', 'Bitores Méndez', 'img/retratos/mendez.webp', 'Jefe del pueblo español y primer gran enemigo de Leon.', 'Gigantesco y brutal, Méndez dirige a los Ganados del pueblo y vigila a Ashley y Luis.', 'Resident Evil 4', 'Los Iluminados', 'Fallecido (2004)', 'Desconocido', 32),
  ('hunnigan', 'Ingrid Hunnigan', 'img/retratos/hunnigan.webp', 'Enlace de Leon con el gobierno durante sus misiones.', 'Analista que guía a Leon por radio en España y en otras misiones.', 'Resident Evil 4', 'Gobierno de EE. UU.', 'Viva', 'Desconocido', 33),
  ('comerciante', 'El comerciante', 'img/retratos/comerciante.webp', 'Misterioso vendedor de armas que aparece por todo el pueblo.', 'Con su famoso «What are ya buyin\'?», compra tesoros y vende y mejora armas para Leon.', 'Resident Evil 4', 'Ninguna', 'Desconocido', 'Desconocido', 34),
  ('javier', 'Javier Hidalgo', 'img/ilustraciones/personajes/javier-hidalgo.svg', 'Narcotraficante sudamericano que usó el T-Veronica.', 'Para curar a su hija Manuela la sometió al T-Veronica. Leon y Krauser lo detuvieron en la Operación Javier (2002).', 'Resident Evil: The Darkside Chronicles', 'Cártel', 'Fallecido (2002)', 'Desconocido', 35),
  ('sheva', 'Sheva Alomar', 'img/retratos/sheva.webp', 'Agente africana de la BSAA, compañera de Chris en Kijuju.', 'Huérfana a causa del bioterrorismo, Sheva se unió a la BSAA y luchó junto a Chris contra Wesker y Excella.', 'Resident Evil 5', 'BSAA', 'Viva', '1986', 36),
  ('excella', 'Excella Gionne', 'img/retratos/excella.webp', 'Ejecutiva de Tricell que ayudó a Wesker.', 'Ambiciosa y aliada de Wesker, financió el proyecto Uroboros. Él la traicionó inyectándole el virus.', 'Resident Evil 5', 'Tricell', 'Fallecida (2009)', 'Desconocido', 37),
  ('irving', 'Ricardo Irving', 'img/ilustraciones/personajes/irving.svg', 'Traficante de bioarmas al servicio de Excella.', 'Intentó vender armas biológicas en el mercado negro y acabó transformado en una criatura acuática por las Plagas.', 'Resident Evil 5', 'Tricell', 'Fallecido (2009)', 'Desconocido', 38),
  ('parker', 'Parker Luciani', 'img/ilustraciones/personajes/parker.svg', 'Compañero de Jill en la BSAA durante Revelations.', 'Agente italiano de la FBC antes de pasarse a la BSAA. Acompaña a Jill a bordo del Queen Zenobia.', 'Resident Evil: Revelations', 'BSAA', 'Vivo', 'Desconocido', 39),
  ('lansdale', 'Morgan Lansdale', 'img/ilustraciones/personajes/lansdale.svg', 'Comisario de la FBC que provocó el desastre de Terragrigia.', 'Dirigía la Federal Bioterrorism Commission. Manipuló a Veltro para aumentar el poder de su organización.', 'Resident Evil: Revelations', 'FBC', 'Detenido', 'Desconocido', 40),
  ('piers', 'Piers Nivans', 'img/retratos/piers.webp', 'Francotirador de la BSAA y mano derecha de Chris.', 'Se inyectó el Virus-C para salvar a Chris y se sacrificó en el laboratorio submarino de Neo-Umbrella.', 'Resident Evil 6', 'BSAA', 'Fallecido (2013)', 'Desconocido', 41),
  ('jake', 'Jake Muller', 'img/retratos/jake.webp', 'Mercenario e hijo de Albert Wesker.', 'Su sangre contiene anticuerpos contra el Virus-C, lo que lo convierte en la esperanza de una vacuna.', 'Resident Evil 6', 'Mercenario', 'Vivo', '1992', 42),
  ('helena', 'Helena Harper', 'img/retratos/helena.webp', 'Agente del Servicio Secreto que acompaña a Leon en Tall Oaks.', 'Simmons la chantajeó para que permitiera el ataque contra el presidente. Después ayudó a Leon a destaparlo.', 'Resident Evil 6', 'Servicio Secreto de EE. UU.', 'Viva', 'Desconocido', 43),
  ('simmons', 'Derek C. Simmons', 'img/retratos/simmons.webp', 'Asesor de seguridad nacional y líder de La Familia.', 'Ordenó la muerte del presidente Benford para ocultar Raccoon City. Infectado con el Virus-C, fue eliminado por Leon y Helena.', 'Resident Evil 6', 'Gobierno de EE. UU., La Familia', 'Fallecido (2013)', 'Desconocido', 44),
  ('carla', 'Carla Radames', 'img/retratos/carla.webp', 'Científica clonada como Ada Wong que creó el Virus-C.', 'Simmons la transformó para que se pareciera a Ada. Resentida, lideró Neo-Umbrella y liberó el Virus-C por el mundo.', 'Resident Evil 6', 'Neo-Umbrella', 'Fallecida (2013)', 'Desconocido', 45),
  ('benford', 'Adam Benford', 'img/retratos/benford.webp', 'Presidente de EE. UU. que quería contar la verdad sobre Raccoon City.', 'Fue el primer jefe de Leon en el gobierno. Iba a revelar la verdad sobre Raccoon City cuando fue infectado en Tall Oaks.', 'Resident Evil: Degeneration', 'Gobierno de EE. UU.', 'Fallecido (2012)', 'Desconocido', 46),
  ('moira', 'Moira Burton', 'img/ilustraciones/personajes/moira.svg', 'Hija de Barry que sobrevive a la isla Sushestvovanie junto a Claire.', 'Moira se niega a usar armas de fuego por un trauma familiar, pero su linterna y su ingenio salvan a Claire una y otra vez.', 'Resident Evil: Revelations 2', 'TerraSave', 'Viva', 'Desconocido', 47),
  ('natalia', 'Natalia Korda', 'img/ilustraciones/personajes/natalia.svg', 'Niña capaz de percibir a las criaturas, elegida por Alex Wesker.', 'Barry la encuentra sola en la isla. Alex Wesker la quiere como recipiente para transferir su consciencia.', 'Resident Evil: Revelations 2', 'Ninguna', 'Viva', 'Desconocido', 48),
  ('alex-wesker', 'Alex Wesker', 'img/ilustraciones/personajes/alex-wesker.svg', 'Hermana adoptiva de Albert Wesker y supervisora de Sushestvovanie.', 'Otra de las niñas del proyecto Wesker. Experimentó con el virus t-Phobos buscando la inmortalidad.', 'Resident Evil: Revelations 2', 'Proyecto Wesker', 'Fallecida', 'Desconocido', 49),
  ('ethan', 'Ethan Winters', 'img/retratos/ethan.webp', 'Hombre corriente que se enfrentó a los Baker y a Madre Miranda.', 'Buscando a su mujer Mia llegó a Luisiana, donde fue infectado por el Moho. Tres años después dio la vida para salvar a su hija Rose.', 'Resident Evil 7: Biohazard', 'Ninguna', 'Fallecido (2021)', 'Desconocido', 50),
  ('mia', 'Mia Winters', 'img/retratos/mia.webp', 'Esposa de Ethan y agente encubierta de La Conexión.', 'Mia escoltaba a Eveline cuando el barco naufragó en Luisiana. Quedó atrapada en la casa Baker hasta que Ethan la rescató.', 'Resident Evil 7: Biohazard', 'La Conexión (antigua)', 'Viva', 'Desconocido', 51),
  ('rose', 'Rose Winters', 'img/retratos/rose.webp', 'Hija de Ethan y Mia con poderes del Moho.', 'Madre Miranda la secuestró para resucitar a su hija. Años después, en Shadows of Rose, busca librarse de sus poderes.', 'Resident Evil Village', 'Ninguna', 'Viva', '2020', 52),
  ('jack', 'Jack Baker', 'img/retratos/jack.webp', 'Patriarca de la familia Baker, controlado por Eveline.', 'Era un buen hombre hasta que el Moho de Eveline lo convirtió en un asesino casi inmortal.', 'Resident Evil 7: Biohazard', 'Familia Baker', 'Fallecido (2017)', 'Desconocido', 53),
  ('joe', 'Joe Baker', 'img/retratos/jo.webp', 'Hermano de Jack Baker que vive en los pantanos de Luisiana.', 'Joe vivía apartado de la familia y no fue infectado por el Moho. En el episodio «End of Zoe» se enfrenta a puñetazo limpio a los Moldeados para salvar a su sobrina Zoe.', 'Resident Evil 7: End of Zoe', 'Familia Baker', 'Vivo', 'Desconocido', 54),
  ('marguerite', 'Marguerite Baker', 'img/ilustraciones/personajes/marguerite.svg', 'Matriarca de los Baker, rodeada de insectos.', 'Infectada por Eveline, vive en la casa vieja y controla enjambres de insectos.', 'Resident Evil 7: Biohazard', 'Familia Baker', 'Fallecida (2017)', 'Desconocido', 55),
  ('lucas', 'Lucas Baker', 'img/retratos/lucas.webp', 'Hijo de los Baker, amante de las trampas mortales.', 'Ya era peligroso antes de la infección. Trabajaba en secreto para La Conexión.', 'Resident Evil 7: Biohazard', 'Familia Baker, La Conexión', 'Fallecido (2017)', 'Desconocido', 56),
  ('zoe', 'Zoe Baker', 'img/retratos/zoe.webp', 'Hija de los Baker que ayuda a Ethan a escapar.', 'Zoe resistió parcialmente la influencia de Eveline y guió a Ethan por teléfono. Su tío Joe la salvó en End of Zoe.', 'Resident Evil 7: Biohazard', 'Familia Baker', 'Viva', 'Desconocido', 57),
  ('eveline', 'Eveline', 'img/retratos/eveline.webp', 'Arma biológica con forma de niña creada a partir del Moho.', 'Creada por La Conexión con el ADN de la hija de Madre Miranda, Eveline controla a los infectados y desea una familia.', 'Resident Evil 7: Biohazard', 'La Conexión', 'Fallecida (2017)', 'Desconocido', 58),
  ('miranda', 'Madre Miranda', 'img/retratos/miranda.webp', 'Sacerdotisa de la aldea que dominaba el Megamiceto.', 'Tras perder a su hija Eva en 1919, Miranda dedicó un siglo a experimentar con el Moho. Fue la mentora de Oswell Spencer.', 'Resident Evil Village', 'La aldea', 'Fallecida (2021)', 'Siglo XIX', 59),
  ('dimitrescu', 'Lady Alcina Dimitrescu', 'img/retratos/dimitrescu.webp', 'Aristócrata de casi tres metros que vive en su castillo.', 'La sangre infectada que necesita para vivir la obtiene de las doncellas que atrae al castillo. Gobierna con sus tres hijas.', 'Resident Evil Village', 'Señores de la aldea', 'Fallecida (2021)', 'Desconocido', 60),
  ('donna', 'Donna Beneviento', 'img/retratos/donna.webp', 'Señora de las muñecas, capaz de provocar alucinaciones.', 'Tímida y retraída, habla a través de su muñeca Angie y atrapa a sus víctimas en pesadillas.', 'Resident Evil Village', 'Señores de la aldea', 'Fallecida (2021)', 'Desconocido', 61),
  ('angie', 'Angie', 'img/retratos/angie.webp', 'La muñeca parlante de Donna Beneviento.', 'Vestida de novia, Angie juega al escondite con Ethan en la casa Beneviento.', 'Resident Evil Village', 'Señores de la aldea', 'Destruida (2021)', 'Desconocido', 62),
  ('moreau', 'Salvatore Moreau', 'img/retratos/moreau.webp', 'Señor deforme del embalse que ansía la aprobación de Miranda.', 'El más débil de los cuatro señores. Se transforma en una enorme criatura acuática.', 'Resident Evil Village', 'Señores de la aldea', 'Fallecido (2021)', 'Desconocido', 63),
  ('heisenberg', 'Karl Heisenberg', 'img/retratos/heisenberg.webp', 'Señor de la fábrica con poder sobre el metal.', 'Odia a Miranda y quiere usar a Ethan para derrocarla con su ejército de soldados mecánicos.', 'Resident Evil Village', 'Señores de la aldea', 'Fallecido (2021)', 'Desconocido', 64),
  ('duque', 'El Duque', 'img/retratos/duque.webp', 'Comerciante de la aldea que viaja en su carruaje.', 'Enorme y amable, vende armas, cocina y aconseja a Ethan con un misterioso conocimiento de lo que ocurre.', 'Resident Evil Village', 'Ninguna', 'Desconocido', 'Desconocido', 65),
  ('josh', 'Josh Stone', 'img/retratos/josh.webp', 'Jefe de la división africana de la BSAA.', 'Mentor de Sheva, ayuda a Chris en Kijuju y los rescata al final.', 'Resident Evil 5', 'BSAA', 'Vivo', 'Desconocido', 66),
  ('grace', 'Grace Ashcroft', 'img/retratos/grace.webp', 'Analista del FBI y protagonista de Resident Evil Requiem.', 'Hija de la periodista Alyssa Ashcroft. Sus investigaciones la llevan al hotel Wrenwood, donde murió su madre, y a las ruinas de Raccoon City.', 'Resident Evil Requiem', 'FBI', 'Viva', 'Desconocido', 67),
  ('alyssa', 'Alyssa Ashcroft', 'img/retratos/alyssa.webp', 'Periodista superviviente de Raccoon City y madre de Grace.', 'Una de las protagonistas de Outbreak. Investigaba a Umbrella y años más tarde murió en el hotel Wrenwood.', 'Resident Evil Outbreak', 'Prensa', 'Fallecida', 'Desconocido', 68),
  ('gideon', 'Victor Gideon', 'img/retratos/gideon.webp', 'Inquietante científico vinculado a los sucesos de Requiem.', 'Figura central de los experimentos que Grace investiga en Resident Evil Requiem.', 'Resident Evil Requiem', 'Desconocida', 'Desconocido', 'Desconocido', 69),
  ('zeno', 'Zeno', 'img/retratos/zeno.webp', 'Misterioso hombre de Requiem de parecido inquietante con Wesker.', 'Personaje enigmático de Resident Evil Requiem cuyas gafas oscuras y porte recuerdan a Albert Wesker.', 'Resident Evil Requiem', 'Desconocida', 'Desconocido', 'Desconocido', 70);
INSERT INTO personaje_imagenes (personaje_id, imagen, orden) VALUES
  ('leon', 'img/retratos/leon_re2.webp', 1),
  ('leon', 'img/retratos/leon_re6.webp', 2),
  ('leon', 'img/retratos/leon_re9.webp', 3),
  ('jill', 'img/retratos/jill_re5.webp', 1),
  ('jill', 'img/retratos/jill_p30.webp', 2),
  ('chris', 'img/retratos/chris_re6.webp', 1),
  ('chris', 'img/retratos/chris_re7.webp', 2),
  ('chris', 'img/retratos/chris_re8.webp', 3),
