  ('sherry', 'img/retratos/sherry_nina.webp', 1);
INSERT INTO criaturas (id, nombre, imagen, resumen, descripcion, origen, primera_aparicion, peligrosidad, orden) VALUES
  ('zombi', 'Zombi', 'img/retratos/zombi.webp', 'Persona infectada por el Virus-T que ha perdido la razón y solo busca alimentarse.', 'El Virus-T destruye la mayor parte del cerebro y deja al huésped con un hambre constante. Son lentos pero resistentes y se cuentan por miles tras un brote como el de Raccoon City.', 'Virus-T', 'Resident Evil (1996)', 2, 1),
  ('crimson-head', 'Crimson Head', 'img/ilustraciones/criaturas/crimson-head.svg', 'Zombi que vuelve a levantarse más rápido y agresivo.', 'Si un zombi abatido no se quema o se decapita, puede despertar como Crimson Head, con garras y una velocidad temible.', 'Virus-T', 'Resident Evil (remake)', 3, 2),
  ('cerberus', 'Cerberus', 'img/retratos/perro.webp', 'Dóberman infectado por el Virus-T.', 'Los perros de Umbrella fueron las primeras víctimas de la fuga en Arklay. Atacan en jauría y saltan sobre su presa.', 'Virus-T', 'Resident Evil (1996)', 2, 3),
  ('hunter', 'Hunter', 'img/retratos/hunter.webp', 'Bioarma reptiliana capaz de decapitar de un zarpazo.', 'Creado mezclando ADN humano y de reptil con el Virus-T. Es rápido, obediente y letal.', 'Virus-T', 'Resident Evil (1996)', 4, 4),
  ('chimera', 'Chimera', 'img/ilustraciones/criaturas/chimera.svg', 'Fusión de humano y mosca que cuelga del techo.', 'Experimento del laboratorio de Arklay que combina ADN humano y de insecto.', 'Virus-T', 'Resident Evil (1996)', 3, 5),
  ('yawn', 'Yawn', 'img/ilustraciones/criaturas/yawn.svg', 'Serpiente gigante que acecha en la mansión.', 'Una serpiente expuesta al Virus-T que creció hasta más de 15 metros. Su veneno es mortal.', 'Virus-T', 'Resident Evil (1996)', 4, 6),
  ('planta-42', 'Planta 42', 'img/ilustraciones/criaturas/planta-42.svg', 'Planta mutada que invade la residencia de la mansión.', 'El agua contaminada con Virus-T convirtió esta planta en un monstruo que caza con sus lianas.', 'Virus-T', 'Resident Evil (1996)', 3, 7),
  ('lisa-trevor', 'Lisa Trevor', 'img/ilustraciones/criaturas/lisa-trevor.svg', 'Hija del arquitecto de la mansión, sometida a décadas de experimentos.', 'Umbrella la usó como cobaya desde 1967. Sus células ayudaron a crear el Virus-G. Es prácticamente indestructible.', 'Progenitor y otros virus', 'Resident Evil (remake)', 5, 8),
  ('tyrant', 'Tyrant', 'img/ilustraciones/criaturas/tyrant.svg', 'Bioarma humanoide de Umbrella diseñada como soldado perfecto.', 'Los Tyrant se crean infectando con Virus-T a personas compatibles. El modelo T-002 fue el jefe final del primer juego.', 'Virus-T', 'Resident Evil (1996)', 4, 9),
  ('proto-tyrant', 'Proto-Tyrant', 'img/ilustraciones/criaturas/proto-tyrant.svg', 'Prototipo fallido de Tyrant con el corazón al descubierto.', 'Uno de los primeros intentos de Umbrella de crear un Tyrant, con un aspecto deforme y un corazón expuesto.', 'Virus-T', 'Resident Evil 0', 4, 10),
  ('tyrant-t002', 'Tyrant T-002', 'img/ilustraciones/criaturas/tyrant-t002.svg', 'Tyrant del laboratorio de Arklay que liberó Wesker.', 'Wesker lo despertó para probarlo contra S.T.A.R.S. Su enorme garra lo hizo inolvidable.', 'Virus-T', 'Resident Evil (1996)', 5, 11),
  ('mr-x', 'Mr. X (T-103)', 'img/retratos/mrx.webp', 'Tyrant con gabardina que persigue a Leon y Claire.', 'Umbrella lo envió a Raccoon City para recuperar la muestra del Virus-G. Sus pasos resuenan por toda la comisaría.', 'Virus-T', 'Resident Evil 2', 5, 12),
  ('licker', 'Licker', 'img/retratos/licker.webp', 'Zombi mutado, ciego y con una lengua larga y afilada como arma.', 'Cuando un zombi sigue mutando, pierde la piel y los ojos y desarrolla un cerebro expuesto y unas garras enormes. Caza guiándose por el sonido.', 'Virus-T', 'Resident Evil 2', 3, 13),
  ('cocodrilo', 'Cocodrilo gigante', 'img/ilustraciones/criaturas/cocodrilo.svg', 'Caimán gigante de las cloacas de Raccoon City.', 'Un caimán abandonado en las alcantarillas que creció desmesuradamente tras beber agua contaminada.', 'Virus-T', 'Resident Evil 2', 4, 14),
  ('g-adulto', 'G (William Birkin)', 'img/retratos/g_adulto.webp', 'La monstruosa forma de William Birkin tras inyectarse el Virus-G.', 'Muta varias veces durante el juego, cada vez más grande, buscando a su hija Sherry para implantarle un embrión.', 'Virus-G', 'Resident Evil 2', 5, 15),
  ('ivy', 'Ivy', 'img/retratos/ivy.webp', 'Planta humanoide del laboratorio de Umbrella.', 'Bioarma vegetal que patrulla los laboratorios y escupe ácido. Las variantes envenenadas se llaman Poison Ivy.', 'Virus-T', 'Resident Evil 2', 3, 16),
  ('nemesis', 'Nemesis', 'img/retratos/nemesis.webp', 'Tyrant controlado por un parásito y enviado a eliminar a los miembros de S.T.A.R.S.', 'Nemesis es un Tyrant al que se implantó el parásito NE-α, que le da inteligencia para usar armas y seguir órdenes. Su objetivo en Raccoon City es acabar con Jill Valentine.', 'Virus-T y parásito NE-α', 'Resident Evil 3: Nemesis', 5, 17),
  ('drain-deimos', 'Drain Deimos', 'img/ilustraciones/criaturas/drain-deimos.svg', 'Pulga gigante que acecha en Raccoon City.', 'Insecto mutado por el Virus-T que puede infectar a sus víctimas con parásitos.', 'Virus-T', 'Resident Evil 3: Nemesis', 3, 18),
  ('bandersnatch', 'Bandersnatch', 'img/ilustraciones/criaturas/bandersnatch.svg', 'Bioarma con un brazo extensible que agarra desde lejos.', 'Fruto de los experimentos de Umbrella para crear un Tyrant más barato. Aparece en Rockfort.', 'Virus-T', 'Resident Evil Code: Veronica', 3, 19),
  ('nosferatu', 'Nosferatu', 'img/ilustraciones/criaturas/nosferatu.svg', 'Alexander Ashford, convertido en monstruo por el T-Veronica.', 'El padre de Alexia fue usado como cobaya del virus. Encadenado en la Antártida, su aliento es venenoso.', 'T-Veronica', 'Resident Evil Code: Veronica', 4, 20),
  ('reina-sanguijuela', 'Reina Sanguijuela', 'img/ilustraciones/criaturas/reina-sanguijuela.svg', 'Sanguijuela mutada que adoptó la forma de James Marcus.', 'Tras el asesinato de Marcus, la sanguijuela madre absorbió sus recuerdos y buscó vengarse de Umbrella.', 'Virus-T', 'Resident Evil 0', 5, 21),
  ('talos', 'T-A.L.O.S.', 'img/ilustraciones/criaturas/talos.svg', 'Tyrant blindado y conectado a la Reina Roja.', 'La última bioarma de Umbrella, defensa de sus instalaciones en el Cáucaso en 2003.', 'Virus-T', 'Resident Evil: The Umbrella Chronicles', 5, 22),
  ('ganados', 'Ganados', 'img/retratos/ganado.webp', 'Aldeanos controlados por Las Plagas que conservan su inteligencia.', 'A diferencia de los zombis, los Ganados hablan, se organizan y usan herramientas. Obedecen a Los Iluminados porque el parásito responde a una Plaga dominante.', 'Las Plagas', 'Resident Evil 4', 2, 23),
  ('colmillos', 'Colmillos', 'img/retratos/perro.webp', 'Lobos infectados por Las Plagas que custodian el pueblo.', 'De su lomo surgen tentáculos cuando la Plaga se libera.', 'Las Plagas', 'Resident Evil 4', 3, 24),
  ('gigante', 'El Gigante', 'img/retratos/gigante.webp', 'Coloso infectado que lucha con sus propias manos.', 'Bioarma enorme de Los Iluminados. Hay que dañar la Plaga de su espalda para derribarlo.', 'Las Plagas', 'Resident Evil 4', 4, 25),
  ('garrador', 'Garrador', 'img/ilustraciones/criaturas/garrador.svg', 'Guerrero ciego con garras metálicas en las manos.', 'Le arrancaron los ojos para agudizar su oído. Su punto débil es la Plaga de la espalda.', 'Las Plagas', 'Resident Evil 4', 4, 26),
  ('verdugo', 'Verdugo', 'img/retratos/verdugo.webp', 'Guardaespaldas de Salazar que caza desde el techo.', 'Bioarma insectoide casi inmune a las balas. Solo el nitrógeno líquido lo frena.', 'Las Plagas', 'Resident Evil 4', 5, 27),
  ('salvador', 'Dr. Salvador', 'img/retratos/salvador.webp', 'Ganado con motosierra y un saco en la cabeza que recibe a Leon en la aldea.', 'Es el primer gran peligro de RE4: una sola embestida de su motosierra puede decapitar a Leon. Suele aparecer en la plaza del pueblo.', 'Las Plagas', 'Resident Evil 4', 4, 28),
  ('monje', 'Monje de los Iluminados', 'img/retratos/monje.webp', 'Fanáticos encapuchados que custodian el castillo de Salazar.', 'Fieles de la secta de Saddler portadores de Las Plagas. Atacan con escudos, mayales y ballestas, y algunos lanzan dinamita.', 'Las Plagas', 'Resident Evil 4', 3, 29),
  ('regenerador', 'Regenerador', 'img/retratos/regenerador.webp', 'Criatura capaz de regenerar cualquier herida mientras sus Plagas sigan vivas.', 'Creado en el laboratorio de la isla, solo cae si se destruyen las Plagas que lleva en el cuerpo, visibles con mira térmica.', 'Las Plagas', 'Resident Evil 4', 4, 30),
  ('u3', 'U-3 (It)', 'img/ilustraciones/criaturas/u3.svg', 'Monstruo con cola de escorpión que acecha en la isla.', 'Bioarma de Saddler hecha con varias Plagas. Persigue a Leon por las instalaciones.', 'Las Plagas', 'Resident Evil 4', 5, 31),
  ('majini', 'Majini', 'img/retratos/majini.webp', 'Habitantes de Kijuju infectados con Plagas tipo 2.', 'Como los Ganados, conservan la inteligencia y atacan en grupo con armas.', 'Las Plagas tipo 2', 'Resident Evil 5', 2, 32),
  ('ndesu', 'Ndesu', 'img/ilustraciones/criaturas/ndesu.svg', 'Gigante de Kijuju, versión africana de El Gigante.', 'Una enorme criatura que Chris y Sheva derriban con un cañón de satélite.', 'Las Plagas', 'Resident Evil 5', 5, 33),
  ('uroboros-criatura', 'Uroboros (criatura)', 'img/ilustraciones/criaturas/uroboros-criatura.svg', 'Masa de tentáculos negros que devora a los incompatibles.', 'Lo que queda de quien no soporta el virus Uroboros. Es débil al fuego.', 'Uroboros', 'Resident Evil 5', 4, 34),
  ('ooze', 'Ooze', 'img/ilustraciones/criaturas/ooze.svg', 'Infectado del T-Abyss con cuerpo viscoso.', 'Las criaturas típicas del Queen Zenobia, que se arrastran por conductos.', 'T-Abyss', 'Resident Evil: Revelations', 3, 35),
  ('scagdead', 'Scagdead', 'img/ilustraciones/criaturas/scagdead.svg', 'Ooze gigante con un brazo serrado.', 'Una de las amenazas más duras del Queen Zenobia.', 'T-Abyss', 'Resident Evil: Revelations', 4, 36),
  ('afligido', 'Afligido', 'img/ilustraciones/criaturas/afligido.svg', 'Infectado del t-Phobos en la isla Sushestvovanie.', 'El virus t-Phobos reacciona al miedo: quien lo siente, muta en una criatura agresiva.', 't-Phobos', 'Resident Evil: Revelations 2', 3, 37),
  ('haos', 'HAOS', 'img/ilustraciones/criaturas/haos.svg', 'Bioarma colosal surgida de una crisálida de Virus-C.', 'Creada por Carla en el laboratorio submarino. Chris y Piers se enfrentan a ella al final de su campaña.', 'Virus-C', 'Resident Evil 6', 5, 38),
  ('lepotitsa', 'Lepotitsa', 'img/ilustraciones/criaturas/lepotitsa.svg', 'Criatura que expulsa un gas tóxico que convierte en zombis.', 'J\'avo mutado en Edonia que se infla de gas venenoso.', 'Virus-C', 'Resident Evil 6', 3, 39),
  ('ustanak', 'Ustanak', 'img/retratos/ustanak.webp', 'Bioarma con brazo mecánico que persigue a Jake y Sherry.', 'Creado por Neo-Umbrella para capturar a Jake, su brazo cambia de herramienta según la situación.', 'Virus-C', 'Resident Evil 6', 5, 40),
  ('moldeado', 'Moldeado', 'img/retratos/moldeado.webp', 'Criatura del Moho que acecha en la casa Baker.', 'Masa negra con forma humana y fauces enormes, nacida de la influencia de Eveline.', 'Moho', 'Resident Evil 7: Biohazard', 3, 41),
  ('licantropo', 'Licántropo', 'img/retratos/licantropo.webp', 'Aldeanos convertidos en bestias lobunas por Miranda.', 'Rápidos y feroces, cazan en manada por la aldea. Los dirige Heisenberg o Miranda.', 'Cadou', 'Resident Evil Village', 3, 42),
  ('hijas', 'Hijas de Dimitrescu', 'img/retratos/hija.webp', 'Bela, Cassandra y Daniela, enjambres de insectos con forma humana.', 'Las tres hijas de Lady Dimitrescu son vulnerables al frío del exterior del castillo.', 'Cadou', 'Resident Evil Village', 4, 43),
  ('soldat', 'Soldat', 'img/ilustraciones/criaturas/soldat.svg', 'Soldado mecánico de Heisenberg.', 'Cadáveres infectados con un Cadou y fusionados con maquinaria en la fábrica.', 'Cadou', 'Resident Evil Village', 4, 44),
  ('reina-roja', 'Reina Roja', 'img/ilustraciones/criaturas/reina-roja.svg', 'Inteligencia artificial que vigila las instalaciones de Umbrella.', 'Se presenta como el holograma de una niña y controla puertas, defensas y protocolos de contención. No es un ser vivo, pero no duda en sacrificar al personal para frenar un brote.', 'Inteligencia artificial de Umbrella', 'Resident Evil (película, 2002)', 4, 45);
INSERT INTO criatura_imagenes (criatura_id, imagen, orden) VALUES
  ('verdugo', 'img/ilustraciones/criaturas/verdugo.svg', 1);
INSERT INTO virus (id, nombre, imagen, resumen, descripcion, tipo, creador, primera_aparicion, orden) VALUES
  ('progenitor', 'Virus Progenitor', 'img/ilustraciones/virus/progenitor.svg', 'Virus ancestral hallado en una flor africana, origen de casi todo.', 'Descubierto en la flor Escalera del Sol, en África occidental, en 1966. A partir de él Umbrella creó el Virus-T.', 'Virus', 'Natural (descubierto por Spencer y Marcus)', 'Resident Evil 0', 1),
  ('virus-t', 'Virus-T', 'img/ilustraciones/virus/t-virus.svg', 'El virus de Umbrella que convirtió Raccoon City en una ciudad de muertos.', 'Desarrollado a partir del Progenitor, el Virus-T reactiva células muertas y provoca mutaciones. Su fuga en la Mansión Spencer y después en Raccoon City dio inicio a la saga.', 'Virus', 'James Marcus / Umbrella', 'Resident Evil (1996)', 2),
  ('virus-g', 'Virus-G', 'img/ilustraciones/virus/g-virus.svg', 'Creación de William Birkin que provoca mutaciones casi ilimitadas.', 'Hace que el huésped evolucione sin parar y pueda reproducirse implantando embriones. Birkin se lo inyectó para no entregarlo a Umbrella.', 'Virus', 'William Birkin', 'Resident Evil 2', 3),
  ('t-veronica', 'T-Veronica', 'img/ilustraciones/virus/t-veronica.svg', 'Virus de Alexia Ashford que permite conservar la inteligencia.', 'Combinación del Virus-T con un virus antiguo de hormigas reina. Requiere años de adaptación en frío.', 'Virus', 'Alexia Ashford', 'Resident Evil Code: Veronica', 4),
  ('plagas', 'Las Plagas', 'img/ilustraciones/virus/las-plagas.svg', 'Parásito antiguo que permite controlar a las personas infectadas.', 'Estuvieron encerradas bajo un castillo español durante siglos. Los Iluminados las recuperaron para controlar a los aldeanos.', 'Parásito', 'Los Iluminados (Osmund Saddler)', 'Resident Evil 4', 5),
  ('t-abyss', 'T-Abyss', 'img/ilustraciones/virus/t-abyss.svg', 'Variante del Virus-T con ADN de peces de las profundidades.', 'Usado por Veltro en Terragrigia y a bordo del Queen Zenobia. Crea los Ooze.', 'Virus', 'Veltro / FBC', 'Resident Evil: Revelations', 6),
  ('uroboros', 'Uroboros', 'img/ilustraciones/virus/uroboros.svg', 'El virus con el que Wesker quería elegir a los supervivientes de la humanidad.', 'Creado a partir del Progenitor, destruye a quien no es compatible y da un enorme poder a los pocos que lo son.', 'Virus', 'Albert Wesker / Tricell', 'Resident Evil 5', 7),
  ('t-phobos', 't-Phobos', 'img/ilustraciones/virus/t-phobos.svg', 'Virus que se activa con el miedo.', 'Alex Wesker lo diseñó para seleccionar personas capaces de controlar el miedo. Quien no puede, muta en Afligido.', 'Virus', 'Alex Wesker', 'Resident Evil: Revelations 2', 8),
  ('virus-c', 'Virus-C', 'img/ilustraciones/virus/c-virus.svg', 'Virus de Neo-Umbrella responsable de los ataques mundiales de 2013.', 'Creado por Carla Radames a partir de los virus T-Veronica y G, puede producir zombis, J\'avo o crisálidas.', 'Virus', 'Carla Radames / Neo-Umbrella', 'Resident Evil 6', 9),
  ('a-virus', 'Virus-A', 'img/ilustraciones/virus/a-virus.svg', 'Virus de Glenn Arias capaz de crear zombis que obedecen órdenes.', 'Liberado en Nueva York en Vendetta. Permite reconocer amigos y enemigos.', 'Virus', 'Glenn Arias', 'Resident Evil: Vendetta', 10),
  ('megamiceto', 'Megamiceto', 'img/ilustraciones/virus/megamiceto.svg', 'Hongo gigantesco bajo la aldea, origen del Moho.', 'Organismo colectivo que almacena la memoria de los seres que absorbe. Madre Miranda lo usó durante un siglo.', 'Hongo', 'Natural', 'Resident Evil Village', 11),
  ('moho', 'Moho (Mutamiceto)', 'img/ilustraciones/virus/moho-e.svg', 'Hongo con memoria procedente del Megamiceto.', 'Permite regenerarse o cambiar de forma. De él nació Eveline (E-001) y causó los horrores de Luisiana.', 'Hongo', 'La Conexión / Madre Miranda', 'Resident Evil 7: Biohazard', 12),
  ('cadou', 'Cadou', 'img/ilustraciones/virus/cadou.svg', 'Parásito creado por Miranda para dar poderes a los señores.', 'Solo unos pocos huéspedes lo toleran; los demás se convierten en licántropos o mueren.', 'Parásito', 'Madre Miranda', 'Resident Evil Village', 13);
INSERT INTO organizaciones (id, nombre, imagen, resumen, descripcion, tipo, fundacion, lider, estado, orden) VALUES
  ('umbrella', 'Umbrella Corporation', 'img/ilustraciones/organizaciones/umbrella.svg', 'Farmacéutica que escondía un programa secreto de armas biológicas.', 'Fundada por Oswell E. Spencer, Edward Ashford y James Marcus, Umbrella vendía medicamentos mientras desarrollaba bioarmas. Tras Raccoon City, quebró en 2003.', 'Corporación farmacéutica', '1968', 'Oswell E. Spencer', 'Disuelta (2003)', 1),
  ('stars', 'S.T.A.R.S.', 'img/ilustraciones/organizaciones/stars.svg', 'Unidad de operaciones especiales de la policía de Raccoon City.', 'Special Tactics And Rescue Service. Sus equipos Alpha y Bravo investigaron los asesinatos de las montañas Arklay y descubrieron la verdad sobre Umbrella. Su capitán, Albert Wesker, los traicionó.', 'Unidad policial', 'Años 60', 'Albert Wesker (capitán)', 'Disuelta (1998)', 2),
  ('ubcs', 'U.B.C.S.', 'img/ilustraciones/organizaciones/ubcs.svg', 'Mercenarios de Umbrella enviados a Raccoon City.', 'Umbrella Biohazard Countermeasure Service. Ex soldados y criminales contratados como carne de cañón para obtener datos de combate.', 'Unidad paramilitar', 'Años 90', 'Umbrella', 'Disuelta (1998)', 3),
  ('bsaa', 'BSAA', 'img/ilustraciones/organizaciones/bsaa.svg', 'Alianza internacional contra el bioterrorismo.', 'La Bioterrorism Security Assessment Alliance nació tras la caída de Umbrella. Chris Redfield y Jill Valentine estuvieron entre sus primeros miembros.', 'Organización antiterrorista', '2003', 'Chris Redfield, Jill Valentine', 'Activa', 4),
  ('dso', 'DSO', 'img/ilustraciones/organizaciones/dso.svg', 'Agencia secreta del gobierno de EE. UU. donde trabaja Leon.', 'La Division of Security Operations coordina las respuestas a amenazas biológicas directamente para la Casa Blanca.', 'Agencia gubernamental', 'Años 2000', 'Presidencia de EE. UU.', 'Activa', 5),
  ('fbc', 'FBC', 'img/ilustraciones/organizaciones/fbc.svg', 'Comisión federal contra el bioterrorismo, rival de la BSAA.', 'La Federal Bioterrorism Commission fue desmantelada tras descubrirse que su jefe, Morgan Lansdale, estaba detrás de Veltro.', 'Agencia gubernamental', '2003', 'Morgan Lansdale', 'Disuelta (2005)', 6),
  ('iluminados', 'Los Iluminados', 'img/escenarios/re4_castillo.webp', 'Secta religiosa española que controla Las Plagas.', 'Liderada por Osmund Saddler, recuperó Las Plagas de los sótanos del castillo de Salazar y las usó para someter al pueblo.', 'Secta religiosa', 'Siglos atrás', 'Osmund Saddler', 'Desmantelada (2004)', 7),
  ('veltro', 'Veltro', 'img/ilustraciones/organizaciones/veltro.svg', 'Grupo terrorista que arrasó Terragrigia.', 'Liberó el T-Abyss en la ciudad flotante de Terragrigia en 2004. Era una marioneta de la FBC.', 'Grupo terrorista', 'Años 2000', 'Jack Norman', 'Desaparecido', 8),
  ('tricell', 'Tricell', 'img/ilustraciones/organizaciones/tricell.svg', 'Multinacional que heredó la investigación de Umbrella en África.', 'Bajo la dirección de Excella Gionne, su división africana financió en secreto el proyecto Uroboros de Wesker.', 'Corporación multinacional', 'Siglo XIX', 'Excella Gionne', 'En decadencia', 9),
  ('terrasave', 'TerraSave', 'img/ilustraciones/organizaciones/terrasave.svg', 'ONG que ayuda a las víctimas del bioterrorismo.', 'TerraSave denuncia a las corporaciones que fabrican armas biológicas y asiste a los supervivientes. Claire Redfield es su miembro más conocida.', 'ONG', 'Años 2000', 'Claire Redfield', 'Activa', 10),
  ('la-familia', 'La Familia', 'img/ilustraciones/organizaciones/la-familia.svg', 'Sociedad secreta que manipula el orden mundial desde las sombras.', 'Derek Simmons la dirigía y no dudó en sacrificar ciudades enteras para mantener su poder.', 'Sociedad secreta', 'Desconocida', 'Derek C. Simmons', 'Desconocido', 11),
  ('neo-umbrella', 'Neo-Umbrella', 'img/ilustraciones/organizaciones/neo-umbrella.svg', 'Organización bioterrorista que usó el Virus-C en 2012-2013.', 'Liderada por Carla Radames bajo la identidad de Ada Wong, atacó Edonia, Tall Oaks y Lanshiang.', 'Grupo bioterrorista', '2012', 'Carla Radames', 'Desmantelada (2013)', 12),
  ('connections', 'La Conexión', 'img/ilustraciones/organizaciones/connections.svg', 'Grupo criminal que vendía bioarmas creadas con el Moho.', 'The Connections creó a Eveline y causó el desastre de Luisiana. Mia Winters fue una de sus agentes.', 'Organización criminal', 'Desconocida', 'Desconocido', 'Desmantelada', 13);
INSERT INTO lugares (id, nombre, imagen, resumen, descripcion, region, primera_aparicion, anio, orden) VALUES
  ('raccoon-city', 'Raccoon City', 'img/escenarios/re2_calle.webp', 'Ciudad del Medio Oeste de EE. UU. destruida tras el brote del Virus-T.', 'Umbrella era la mayor empresa de la ciudad y tenía bajo ella el laboratorio NEST. En septiembre de 1998 el virus se extendió y el 1 de octubre el gobierno la arrasó con un misil.', 'Medio Oeste, EE. UU.', 'Resident Evil 2', 1998, 1),
  ('montanas-arklay', 'Montañas Arklay', 'img/ilustraciones/ubicaciones/montanas-arklay.svg', 'Bosque a las afueras de Raccoon City donde empezó todo.', 'Los extraños asesinatos de excursionistas en 1998 llevaron a S.T.A.R.S. a investigar la zona.', 'Raccoon City, EE. UU.', 'Resident Evil (1996)', 1998, 2),
  ('mansion-spencer', 'Mansión Spencer', 'img/ilustraciones/ubicaciones/mansion-spencer.svg', 'Mansión llena de trampas que escondía el laboratorio de Arklay.', 'Construida por George Trevor para Spencer, ocultaba pasadizos, acertijos y un laboratorio. Fue destruida en julio de 1998.', 'Montañas Arklay, EE. UU.', 'Resident Evil (1996)', 1998, 3),
  ('laboratorio-arklay', 'Laboratorio de Arklay', 'img/ilustraciones/ubicaciones/laboratorio-arklay.svg', 'Laboratorio secreto bajo la mansión donde se fugó el Virus-T.', 'Allí trabajaron Wesker y Birkin y nacieron los primeros Tyrant.', 'Montañas Arklay, EE. UU.', 'Resident Evil (1996)', 1998, 4),
  ('ecliptic-express', 'Ecliptic Express', 'img/ilustraciones/ubicaciones/ecliptic-express.svg', 'Tren de lujo de Umbrella atacado por las sanguijuelas de Marcus.', 'Aquí se conocieron Rebecca y Billy en la noche del 23 de julio de 1998.', 'Montañas Arklay, EE. UU.', 'Resident Evil 0', 1998, 5),
  ('centro-formacion', 'Centro de formación de Umbrella', 'img/ilustraciones/ubicaciones/centro-formacion-umbrella.svg', 'Escuela de ejecutivos de Umbrella dirigida por James Marcus.', 'Allí estudiaron Wesker y Birkin. Cerró tras el asesinato de Marcus en 1988.', 'Montañas Arklay, EE. UU.', 'Resident Evil 0', 1998, 6),
  ('rpd', 'Comisaría R.P.D.', 'img/escenarios/re2_vestibulo.webp', 'Comisaría de Raccoon City instalada en un antiguo museo de arte.', 'Su jefe, Brian Irons, la llenó de estatuas y pasadizos. Durante el brote fue refugio y trampa para Leon y Claire.', 'Raccoon City', 'Resident Evil 2', 1998, 7),
  ('orfanato', 'Orfanato de Raccoon City', 'img/escenarios/re2_orfanato.webp', 'Orfanato vinculado a Irons y a los experimentos de Umbrella.', 'En el remake de RE2, Sherry acaba encerrada aquí por el jefe Irons.', 'Raccoon City', 'Resident Evil 2 (remake)', 1998, 8),
  ('nest', 'Laboratorio NEST', 'img/escenarios/re2_nest.webp', 'Gran complejo subterráneo de Umbrella bajo Raccoon City.', 'Allí se desarrollaron el Virus-G y la vacuna DEVIL. Se autodestruyó al final de RE2.', 'Raccoon City', 'Resident Evil 2', 1998, 9),
  ('hospital-spencer', 'Hospital Spencer Memorial', 'img/escenarios/re3_hospital.webp', 'Hospital donde Jill y Carlos buscan la vacuna.', 'Gestionado por Umbrella, se convirtió en uno de los focos del brote.', 'Raccoon City', 'Resident Evil 3 (remake)', 1998, 10),
  ('isla-rockfort', 'Isla Rockfort', 'img/ilustraciones/ubicaciones/isla-rockfort.svg', 'Isla prisión de la familia Ashford donde Claire es encarcelada.', 'Tenía una prisión y un centro de entrenamiento de Umbrella. Un ataque liberó el Virus-T y Claire huyó con Steve Burnside.', 'Hemisferio sur', 'Resident Evil Code: Veronica', 1998, 11),
  ('base-antartica', 'Base de la Antártida', 'img/ilustraciones/ubicaciones/base-antartica.svg', 'Instalación de los Ashford donde despierta Alexia.', 'Escenario del final de Code: Veronica y del enfrentamiento de Chris con Wesker.', 'Antártida', 'Resident Evil Code: Veronica', 1998, 12),
  ('paris-umbrella', 'Laboratorio de Umbrella en París', 'img/ilustraciones/ubicaciones/paris-umbrella.svg', 'Instalación donde Claire es capturada.', 'Claire se infiltró aquí buscando a Chris en diciembre de 1998.', 'París, Francia', 'Resident Evil Code: Veronica', 1998, 13),
  ('caucaso', 'Instalaciones del Cáucaso', 'img/ilustraciones/ubicaciones/caucaso-umbrella.svg', 'Última base de Umbrella, protegida por la Reina Roja.', 'En 2003 Chris y Jill la asaltaron y pusieron fin a la compañía.', 'Rusia', 'Resident Evil: The Umbrella Chronicles', 2003, 14),
  ('amparo', 'Amparo', 'img/ilustraciones/ubicaciones/amparo.svg', 'Región de Sudamérica donde tuvo lugar la Operación Javier.', 'Leon y Krauser persiguen aquí a Javier Hidalgo en 2002, en plena selva y entre ruinas.', 'Sudamérica', 'Resident Evil: The Darkside Chronicles', 2002, 15),
  ('pueblo-espana', 'Pueblo de España', 'img/escenarios/re4_plaza.webp', 'Aldea rural dominada por Los Iluminados y sus Ganados.', 'Leon llega siguiendo la pista de Ashley Graham. De la plaza a la granja, todos los vecinos están infectados.', 'España', 'Resident Evil 4', 2004, 16),
  ('castillo-salazar', 'Castillo de Salazar', 'img/escenarios/re4_castillo.webp', 'Fortaleza del castellano Ramón Salazar.', 'Bajo sus cimientos estuvieron selladas Las Plagas durante siglos.', 'España', 'Resident Evil 4', 2004, 17),
  ('isla-saddler', 'Isla de Saddler', 'img/escenarios/re4_isla.webp', 'Base militar de Los Iluminados frente a la costa.', 'Aquí se crean los Regeneradores y Leon libera por fin a Ashley.', 'España', 'Resident Evil 4', 2004, 18),
  ('terragrigia', 'Terragrigia', 'img/ilustraciones/ubicaciones/terragrigia.svg', 'Ciudad flotante del Mediterráneo destruida por Veltro.', 'Modelo de ciudad sostenible que acabó arrasada por un satélite solar para contener el T-Abyss en 2004.', 'Mediterráneo', 'Resident Evil: Revelations', 2004, 19),
  ('queen-zenobia', 'Queen Zenobia', 'img/ilustraciones/ubicaciones/queen-zenobia.svg', 'Crucero de lujo convertido en laboratorio flotante.', 'Jill y Parker lo exploran en 2005 buscando a Chris.', 'Mediterráneo', 'Resident Evil: Revelations', 2005, 20),
  ('harvardville', 'Aeropuerto de Harvardville', 'img/ilustraciones/ubicaciones/harvardville.svg', 'Aeropuerto atacado con Virus-T en 2005.', 'Leon y Claire vuelven a coincidir aquí en Degeneration.', 'EE. UU.', 'Resident Evil: Degeneration', 2005, 21),
  ('kijuju', 'Kijuju', 'img/escenarios/re5_kijuju.webp', 'Región africana donde Chris y Sheva luchan contra los Majini.', 'Incluye el pueblo, los campos, las ruinas y el barco de Tricell.', 'África', 'Resident Evil 5', 2009, 22),
  ('mansion-spencer-europa', 'Finca de Spencer en Europa', 'img/ilustraciones/ubicaciones/mansion-spencer-europa.svg', 'Residencia donde Wesker mata a Spencer.', 'En 2006 Chris y Jill la asaltaron buscando a Spencer y encontraron a Wesker.', 'Europa', 'Resident Evil 5', 2006, 23),
  ('republica-eslava', 'República Eslava del Este', 'img/ilustraciones/ubicaciones/republica-eslava.svg', 'País en guerra civil donde se usan Plagas como armas.', 'Escenario de Damnation, en 2011.', 'Europa del Este', 'Resident Evil: Damnation', 2011, 24),
  ('sushestvovanie', 'Isla Sushestvovanie', 'img/ilustraciones/ubicaciones/sushestvovanie.svg', 'Isla prisión de Alex Wesker.', 'Claire y Moira despiertan aquí en 2011 y Barry llega seis meses después.', 'Europa del Este', 'Resident Evil: Revelations 2', 2011, 25),
  ('edonia', 'Edonia', 'img/ilustraciones/ubicaciones/edonia.svg', 'País europeo en conflicto donde Chris pierde a su escuadrón.', 'Primer gran ataque con J\'avo de Neo-Umbrella, en diciembre de 2012.', 'Europa del Este', 'Resident Evil 6', 2012, 26),
  ('tall-oaks', 'Tall Oaks', 'img/escenarios/re6_tallaoks.webp', 'Ciudad estadounidense arrasada por el Virus-C.', 'El presidente Benford iba a revelar la verdad sobre Raccoon City en su universidad.', 'EE. UU.', 'Resident Evil 6', 2013, 27),
  ('lanshiang', 'Lanshiang', 'img/escenarios/re6_lanshiang.webp', 'Metrópolis china atacada con Virus-C.', 'Las cuatro campañas de RE6 convergen en sus calles.', 'China', 'Resident Evil 6', 2013, 28),
  ('laboratorio-submarino', 'Laboratorio submarino de Neo-Umbrella', 'img/ilustraciones/ubicaciones/laboratorio-submarino.svg', 'Base bajo el mar donde Carla crea a HAOS.', 'Chris y Piers la asaltan al final de RE6. Piers se sacrifica para que Chris escape.', 'Océano', 'Resident Evil 6', 2013, 29),
  ('penamstan', 'Penamstan', 'img/ilustraciones/ubicaciones/penamstan.svg', 'País en guerra donde EE. UU. probó un arma biológica.', 'Origen de la conspiración de Infinite Darkness.', 'Asia', 'Infinite Darkness', 2000, 30),
  ('finlandia', 'Montañas de Finlandia', 'img/ilustraciones/ubicaciones/finlandia.svg', 'Montañas nevadas donde Chris y Jessica buscan a Veltro.', 'Al comienzo de Revelations, Chris y Jessica Sherawat siguen la pista de la organización terrorista Veltro por las montañas finlandesas.', 'Europa', 'Resident Evil: Revelations', 2005, 31),
  ('nueva-york', 'Nueva York', 'img/ilustraciones/ubicaciones/nueva-york.svg', 'Ciudad atacada con el Virus-A en Vendetta.', 'Chris, Leon y Rebecca detienen a Glenn Arias en Manhattan.', 'EE. UU.', 'Resident Evil: Vendetta', 2014, 32),
  ('alcatraz', 'Alcatraz', 'img/ilustraciones/ubicaciones/alcatraz.svg', 'Isla prisión de San Francisco, escenario de Death Island.', 'Un nuevo brote reúne aquí a los cinco grandes héroes de la saga.', 'San Francisco, EE. UU.', 'Resident Evil: Death Island', 2015, 33),
  ('casa-baker', 'Casa de los Baker', 'img/escenarios/re7_comedor.webp', 'Granja de Dulvey, Luisiana, donde Ethan busca a Mia.', 'La casa principal, la casa vieja, el granero y el barco naufragado forman el escenario de RE7.', 'Luisiana, EE. UU.', 'Resident Evil 7: Biohazard', 2017, 34),
  ('aldea', 'La aldea', 'img/escenarios/re8_aldea.webp', 'Aldea de Europa del Este gobernada por Madre Miranda.', 'Rodeada por los dominios de los cuatro señores: castillo, casa, embalse y fábrica.', 'Europa del Este', 'Resident Evil Village', 2021, 35),
  ('castillo-dimitrescu', 'Castillo Dimitrescu', 'img/escenarios/re8_castillo.webp', 'Residencia de Lady Dimitrescu y sus tres hijas.', 'Domina la aldea. En sus salones caza a quien se atreve a entrar.', 'Europa del Este', 'Resident Evil Village', 2021, 36),
  ('casa-beneviento', 'Casa Beneviento', 'img/escenarios/re8_beneviento.webp', 'Mansión de las muñecas de Donna Beneviento.', 'Famosa por su secuencia sin armas y el bebé gigante.', 'Europa del Este', 'Resident Evil Village', 2021, 37),
  ('embalse', 'Embalse de Moreau', 'img/escenarios/re8_embalse.webp', 'Embalse donde vive Salvatore Moreau.', 'Ethan cruza el lago en barca mientras Moreau acecha bajo el agua.', 'Europa del Este', 'Resident Evil Village', 2021, 38),
  ('fabrica', 'Fábrica de Heisenberg', 'img/escenarios/re8_fabrica.webp', 'Fábrica donde Heisenberg crea sus soldados mecánicos.', 'Último dominio de los señores antes de enfrentarse a Miranda.', 'Europa del Este', 'Resident Evil Village', 2021, 39),
  ('wrenwood', 'Hotel Wrenwood', 'img/escenarios/re9_hotel.webp', 'Hotel abandonado donde murió Alyssa Ashcroft.', 'Punto de partida de la investigación de Grace en Resident Evil Requiem.', 'EE. UU.', 'Resident Evil Requiem', 2026, 40);
INSERT INTO peliculas (id, nombre, imagen, resumen, descripcion, anio, formato, orden) VALUES
  ('bio4d', 'Biohazard 4D-Executer', 'img/escenarios/re2_nest.webp', 'Cortometraje en CGI para cines 4D de Japón.', 'Un equipo de Umbrella entra en un laboratorio infestado. Fue el primer audiovisual animado de la saga.', 2000, 'Cortometraje CGI', 1),
  ('re-2002', 'Resident Evil (2002)', 'img/escenarios/re3_metro.webp', 'Alice despierta sin memoria sobre la Colmena de Umbrella.', 'Primera película de acción real, dirigida por Paul W. S. Anderson. Un comando entra en la Colmena, controlada por la Reina Roja.', 2002, 'Acción real', 2),
  ('apocalypse', 'Resident Evil: Apocalipsis', 'img/escenarios/re3_calles.webp', 'Alice y Jill intentan escapar de Raccoon City.', 'Incluye a Jill Valentine, Carlos Oliveira y Nemesis. Dirigida por Alexander Witt.', 2004, 'Acción real', 3),
  ('extinction', 'Resident Evil: Extinción', 'img/escenarios/re5_campos.webp', 'El mundo es un desierto y Alice viaja con un convoy de supervivientes.', 'Presenta a Claire Redfield y al doctor Isaacs. Dirigida por Russell Mulcahy.', 2007, 'Acción real', 4),
  ('degeneration', 'Resident Evil: Degeneration', 'img/ilustraciones/ubicaciones/harvardville.svg', 'Leon y Claire se reencuentran durante un brote en el aeropuerto de Harvardville.', 'Primera película de animación por ordenador de la saga. Un ataque con Virus-T lleva a Leon y Claire a descubrir el Virus-G en manos de WilPharma.', 2008, 'Película CGI', 5),
  ('afterlife', 'Resident Evil: Ultratumba', 'img/escenarios/re6_universidad.webp', 'Alice busca Arcadia y se enfrenta a Wesker.', 'Rodada en 3D, reúne a Alice con Claire y Chris Redfield en Los Ángeles.', 2010, 'Acción real', 6),
  ('retribution', 'Resident Evil: Venganza', 'img/escenarios/re6_catacumbas.webp', 'Alice escapa de una base submarina de Umbrella.', 'Aparecen Leon, Ada, Barry y una Jill controlada por Umbrella.', 2012, 'Acción real', 7),
  ('damnation', 'Resident Evil: Damnation', 'img/ilustraciones/ubicaciones/republica-eslava.svg', 'Leon se infiltra en una guerra civil donde se usan Plagas como armas.', 'En la República Eslava, la presidenta Svetlana Belikova controla a sus soldados con Plagas. Leon cuenta con la ayuda de Ada Wong.', 2012, 'Película CGI', 8),
  ('final-chapter', 'Resident Evil: El capítulo final', 'img/escenarios/re2_calle.webp', 'Alice vuelve a Raccoon City para acabar con Umbrella.', 'Cierre de la saga de Paul W. S. Anderson y Milla Jovovich.', 2016, 'Acción real', 9),
  ('vendetta', 'Resident Evil: Vendetta', 'img/ilustraciones/ubicaciones/nueva-york.svg', 'Chris, Leon y Rebecca intentan detener un ataque viral sobre Nueva York.', 'Glenn Arias quiere vengarse liberando el Virus-A en Manhattan. Es la primera película en la que Chris y Leon luchan juntos.', 2017, 'Película CGI', 10),
  ('welcome-raccoon-city', 'Resident Evil: Bienvenidos a Raccoon City', 'img/escenarios/re2_vestibulo.webp', 'Reinicio en acción real fiel a los dos primeros juegos.', 'Dirigida por Johannes Roberts, mezcla la mansión y la comisaría la noche del brote.', 2021, 'Acción real', 11),
  ('infinite-darkness', 'Resident Evil: Infinite Darkness', 'img/ilustraciones/ubicaciones/penamstan.svg', 'Serie de Netflix sobre una conspiración en la Casa Blanca en 2006.', 'Un brote zombi en la Casa Blanca conecta a Leon y Claire con una conspiración que se remonta a la guerra de Penamstan.', 2021, 'Serie CGI', 12),
  ('serie-netflix', 'Resident Evil (serie de Netflix)', 'img/escenarios/re6_bar.webp', 'Serie de acción real sobre las hijas de Albert Wesker.', 'Alterna 2022 en New Raccoon City con un futuro devastado. Se canceló tras una temporada.', 2022, 'Serie de acción real', 13),
  ('death-island', 'Resident Evil: Death Island', 'img/ilustraciones/ubicaciones/alcatraz.svg', 'Los cinco grandes héroes de la saga se reúnen en Alcatraz.', 'Un nuevo brote reúne por primera vez a Leon, Chris, Jill, Claire y Rebecca.', 2023, 'Película CGI', 14),
  ('re-2026', 'Resident Evil (2026)', 'img/escenarios/re9_ruinas.webp', 'Nueva película de acción real dirigida por Zach Cregger.', 'Nuevo reinicio cinematográfico de Sony y Constantin Film, anunciado para 2026.', 2026, 'Acción real', 15);
