INSERT INTO cronologia (id, nombre, imagen, resumen, descripcion, periodo, anio, juego, orden) VALUES
  ('origenes', 'Descubrimiento del Progenitor', 'img/ilustraciones/virus/progenitor.svg', 'Spencer, Marcus y Ashford hallan el virus Progenitor en África.', 'En 1966 se descubre el Progenitor en la flor Escalera del Sol. Es el punto de partida del Virus-T.', '1966', 1966, 'Resident Evil 5 (documentos)', 1),
  ('fundacion-umbrella', 'Fundación de Umbrella', 'img/ilustraciones/organizaciones/umbrella.svg', 'Nace Umbrella como tapadera de la investigación biológica.', 'En 1968 Spencer, Marcus y Ashford fundan Umbrella Corporation.', '1968', 1968, 'Resident Evil 0', 2),
  ('muerte-marcus', 'Asesinato de James Marcus', 'img/ilustraciones/personajes/james-marcus.svg', 'Spencer ordena matar a Marcus; Wesker y Birkin lo ejecutan.', 'En 1988 el creador del Virus-T es eliminado. Diez años después su sanguijuela reina buscará venganza.', '1988', 1988, 'Resident Evil 0', 3),
  ('ecliptic', 'Incidente del Ecliptic Express', 'img/ilustraciones/ubicaciones/ecliptic-express.svg', 'Rebecca y Billy sobreviven al tren infestado.', '23 de julio de 1998. El equipo Bravo de S.T.A.R.S. cae en las montañas Arklay.', 'Julio de 1998', 1998, 'Resident Evil 0', 4),
  ('mansion', 'Incidente de la mansión', 'img/ilustraciones/ubicaciones/mansion-spencer.svg', 'El equipo Alpha descubre el laboratorio de Arklay.', '24 de julio de 1998. Wesker traiciona a S.T.A.R.S. y la mansión es destruida.', 'Julio de 1998', 1998, 'Resident Evil (1996)', 5),
  ('raccoon-1998', 'Incidente de Raccoon City', 'img/escenarios/re2_calle.webp', 'El Virus-T arrasa Raccoon City.', 'Entre septiembre y el 1 de octubre de 1998 el virus se extiende por la ciudad, que es destruida por un misil.', 'Septiembre-octubre de 1998', 1998, 'Resident Evil 2 y Resident Evil 3', 6),
  ('rockfort', 'Incidente de Rockfort', 'img/ilustraciones/ubicaciones/isla-rockfort.svg', 'Claire en la isla Rockfort; Chris contra Wesker en la Antártida.', 'Diciembre de 1998. Alexia Ashford despierta y es derrotada por Chris.', 'Diciembre de 1998', 1998, 'Resident Evil Code: Veronica', 7),
  ('operacion-javier', 'Operación Javier', 'img/ilustraciones/personajes/javier-hidalgo.svg', 'Leon y Krauser contra un narcotraficante con el T-Veronica.', '2002, Sudamérica. Krauser resulta herido y empieza su desencanto.', '2002', 2002, 'Resident Evil: The Darkside Chronicles', 8),
  ('caida-umbrella', 'Caída de Umbrella', 'img/ilustraciones/ubicaciones/caucaso-umbrella.svg', 'Asalto a la base del Cáucaso y quiebra de la compañía.', 'En 2003 Chris y Jill destruyen la última base de Umbrella y el gobierno de EE. UU. retira sus licencias. Se funda la BSAA.', '2003', 2003, 'Resident Evil: The Umbrella Chronicles', 9),
  ('espana-2004', 'Acontecimientos en España', 'img/escenarios/re4_plaza.webp', 'Leon rescata a Ashley Graham de Los Iluminados.', 'Otoño de 2004. Leon se enfrenta a Las Plagas y acaba con Saddler. Ada se lleva una muestra.', '2004', 2004, 'Resident Evil 4', 10),
  ('terragrigia-2004', 'Pánico de Terragrigia', 'img/ilustraciones/ubicaciones/terragrigia.svg', 'Veltro libera el T-Abyss en la ciudad flotante.', 'La ciudad es destruida con el satélite Regia Solis para contener el brote.', '2004', 2004, 'Resident Evil: Revelations', 11),
  ('zenobia-2005', 'Incidente del Queen Zenobia', 'img/ilustraciones/ubicaciones/queen-zenobia.svg', 'Jill y Parker destapan la conspiración de la FBC.', '2005. La FBC queda disuelta y la BSAA pasa a depender de la ONU.', '2005', 2005, 'Resident Evil: Revelations', 12),
  ('harvardville-2005', 'Incidente de Harvardville', 'img/ilustraciones/ubicaciones/harvardville.svg', 'Ataque con Virus-T en un aeropuerto estadounidense.', '2005. Leon y Claire descubren a WilPharma y el Virus-G.', '2005', 2005, 'Resident Evil: Degeneration', 13),
  ('muerte-spencer', 'Muerte de Spencer', 'img/ilustraciones/personajes/spencer.svg', 'Wesker mata a Spencer; Jill desaparece.', '2006. Chris y Jill asaltan la finca de Spencer en Europa y Jill cae por un acantilado con Wesker.', '2006', 2006, 'Resident Evil 5', 14),
  ('kijuju-2009', 'Incidente de Kijuju', 'img/escenarios/re5_kijuju.webp', 'Chris y Sheva acaban con Wesker en África.', '2009. Se frustra el plan Uroboros y Jill es liberada.', '2009', 2009, 'Resident Evil 5', 15),
  ('sushestvovanie-2011', 'Incidente de Sushestvovanie', 'img/ilustraciones/ubicaciones/sushestvovanie.svg', 'Claire y Moira escapan de la isla de Alex Wesker.', '2011. Seis meses después, Barry rescata a Moira y conoce a Natalia.', '2011', 2011, 'Resident Evil: Revelations 2', 16),
  ('virus-c-2013', 'Ataques del Virus-C', 'img/escenarios/re6_lanshiang.webp', 'Neo-Umbrella ataca Edonia, Tall Oaks y Lanshiang.', 'Entre diciembre de 2012 y junio de 2013 muere el presidente Benford y cae Derek Simmons.', '2012-2013', 2013, 'Resident Evil 6', 17),
  ('luisiana-2017', 'Incidente de Luisiana', 'img/escenarios/re7_casa_vieja.webp', 'Ethan Winters busca a su mujer en la granja de los Baker.', 'Ethan llega a Dulvey, donde la familia Baker está controlada por Eveline, un arma biológica creada con el Moho.', '2017', 2017, 'Resident Evil 7: Biohazard', 18),
  ('aldea-2021', 'La aldea europea', 'img/escenarios/re8_aldea.webp', 'Ethan se enfrenta a Madre Miranda para recuperar a Rose.', 'En febrero de 2021 Ethan persigue a quienes secuestraron a su hija por una aldea gobernada por Madre Miranda y sus cuatro señores.', '2021', 2021, 'Resident Evil Village', 19),
  ('requiem', 'Requiem', 'img/escenarios/re9_ruinas.webp', 'Grace Ashcroft sigue el rastro de su madre hasta las ruinas de Raccoon City.', 'La saga vuelve al lugar donde empezó todo, décadas después del brote.', 'Años 2020', 2026, 'Resident Evil Requiem', 20);
INSERT INTO expedientes (id, titulo, nivel, resumen, texto, imagen, orden) VALUES
  ('proyecto-wesker', 'Proyecto Wesker', 'ALTO SECRETO', 'Programa secreto de Umbrella para crear sujetos superiores. Albert Wesker fue uno de sus pocos supervivientes.', 'Oswell E. Spencer reunió a niños superdotados de todo el mundo, les dio el apellido Wesker y los sometió a un virus experimental. Solo Albert y Alex sobrevivieron a las pruebas.', 'img/retratos/wesker.webp', 1),
  ('virus-g', 'Virus G', 'CLASIFICADO', 'Investigación de William Birkin bajo Raccoon City. Su robo provocó la mutación del propio Birkin.', 'Los agentes del U.S.S. dispararon a Birkin para robar sus muestras. Moribundo, se inyectó el virus y se convirtió en G.', 'img/retratos/birkin.webp', 2),
  ('proyecto-nemesis', 'Proyecto Némesis', 'CLASIFICADO', 'Tirano controlado por el parásito NE-α, enviado a eliminar a los miembros supervivientes de S.T.A.R.S.', 'El parásito NE-α, desarrollado en la sede europea de Umbrella, dota al Tyrant de inteligencia para seguir órdenes complejas y usar armas.', 'img/retratos/nemesis.webp', 3);
